package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.database.Cursor;import android.os.Bundle;
import android.provider.*;import android.telephony.PhoneNumberUtils;import java.util.*;

/** Bounded, read-only merged activity across every number of a contact. */
public final class ContactTimelineActivity extends LeoActivity {
    static final class Event {final long date;final String label;final Intent target;Event(long d,String l,Intent i){date=d;label=l;target=i;}}
    static boolean matches(List<String> numbers,String value){if(value==null||value.isEmpty())return false;for(String number:numbers)if(PhoneNumberUtils.compare(number,value))return true;return false;}
    protected void onCreate(Bundle b){super.onCreate(b);final long contact=getIntent().getLongExtra("contact",-1);begin(L.t("Activitatea contactului"));root.addView(text(L.t("Se încarcă…"),17));footer("","",L.t("Înapoi"));worker.execute(new Runnable(){public void run(){final ArrayList<Event> events=read(ContactTimelineActivity.this,contact);ui(new Runnable(){public void run(){ArrayList<String> labels=new ArrayList<>();for(Event e:events)labels.add(android.text.format.DateFormat.format("dd.MM HH:mm",e.date)+" · "+e.label);list(L.t("Activitatea contactului"),labels,0,new Choice(){public void pick(int at){startActivity(events.get(at).target);}},"",null);}});}});}
    static ArrayList<Event> read(Context c,long contact){ArrayList<String> numbers=new ArrayList<>();for(ContactBook.Number n:ContactBook.numbers(c,contact))numbers.add(n.value);ArrayList<Event> result=new ArrayList<>();if(numbers.isEmpty())return result;
        try(Cursor r=c.getContentResolver().query(CallLog.Calls.CONTENT_URI.buildUpon().appendQueryParameter("limit","500").build(),new String[]{"number","date","type","duration"},null,null,"date DESC")){int n=0;while(r!=null&&r.moveToNext()&&n++<500)if(matches(numbers,r.getString(0)))result.add(new Event(r.getLong(1),(r.getInt(2)==CallLog.Calls.MISSED_TYPE?L.t("Apel pierdut"):r.getInt(2)==CallLog.Calls.OUTGOING_TYPE?L.t("Apel efectuat"):L.t("Apel primit"))+" · "+r.getLong(3)+" s",new Intent(c,PhoneActivity.class).putExtra("history",true).putExtra("history_number",r.getString(0))));}catch(RuntimeException ignored){}
        HashSet<String> seen=new HashSet<>();try(Cursor r=c.getContentResolver().query(Telephony.Sms.CONTENT_URI,new String[]{"address","date","body","type"},null,null,"date DESC")){int n=0;while(r!=null&&r.moveToNext()&&n++<1000)addSms(c,numbers,result,seen,r.getString(0),r.getLong(1),r.getString(2),r.getInt(3)==2);}catch(RuntimeException ignored){}
        try(SmsStore db=new SmsStore(c)){for(String table:new String[]{"inbox","outgoing"})try(Cursor r=db.getReadableDatabase().query(table,new String[]{"address","date","body"},null,null,null,null,"date DESC","500")){while(r.moveToNext())addSms(c,numbers,result,seen,r.getString(0),r.getLong(1),r.getString(2),table.equals("outgoing"));}}catch(RuntimeException ignored){}
        Collections.sort(result,new Comparator<Event>(){public int compare(Event a,Event b){return Long.compare(b.date,a.date);}});while(result.size()>80)result.remove(result.size()-1);return result;
    }
    private static void addSms(Context c,List<String> numbers,List<Event> result,Set<String> seen,String address,long date,String body,boolean sent){if(!matches(numbers,address)||body==null||ConversationPrefs.has(c,"blocked",address)||!seen.add(ConversationPrefs.key(address)+"|"+date+"|"+body))return;String preview=body.replace('\n',' ');if(preview.length()>60)preview=preview.substring(0,60)+"…";result.add(new Event(date,(sent?L.t("SMS trimis"):L.t("SMS primit"))+" · "+preview,new Intent(c,MessagesActivity.class).putExtra("thread",address).putExtra("search_date",date)));}
}
